from collections import defaultdict

SIGNOS = ".,;:!?¡¿“”‘’\"'()«»—"

with open("versiculos.json", encoding="utf-8") as f:
    data = json.load(f)

index = defaultdict(list)
for quote in data.values():
    ref = quote["en"]["ref"]
    for word in quote["en"]["texto"].split():
        word = word.strip(SIGNOS).lower()
        if len(word) >= 4 and ref not in index[word]:
            index[word].append(ref)

def search(word):
